        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        self._evaluate_open_position(slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.End
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if not self.Securities[self.spy].Exchange.Hours.IsOpen(
                local_time, False):
            return

        end_minute = local_time.replace(second=0, microsecond=0)
        boundary_minute = ((end_minute.minute + 4) // 5) * 5
        if boundary_minute == 60:
            bucket_end = end_minute.replace(
                hour=end_minute.hour + 1, minute=0)
        else:
            bucket_end = end_minute.replace(minute=boundary_minute)

        bucket_date = bucket_end.date()

        if self.bucket_end != bucket_end:
            self._finalize_bucket()
            self.bucket_date = bucket_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_minute] = minute_bar

        if end_minute == bucket_end - timedelta(minutes=1):
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice=None):
        if self.bucket_end is None:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if not all(t in self.bucket_bars for t in expected):
            self.bucket_bars = {}
            return

        close = self.bucket_bars[expected[0]].Close
        previous_fast = self.fast_values[0] if self.fast_values.IsReady else None
        previous_slow = self.slow_values[0] if self.slow_values.IsReady else None

        self.fast_values.Add(close)
        self.slow_values.Add(close)

        current_time = self.bucket_end.time()
        eligible = time(9, 45) <= current_time <= time(14, 30)

        bullish = (
            previous_fast is not None and
            previous_slow is not None and
            self.fast_values.IsReady and
            self.slow_values.IsReady and
            previous_fast <= previous_slow and
            self.fast_values[0] > self.slow_values[0]
        )

        if eligible and bullish and slice is not None:
            self._try_enter(slice)

        self.bucket_bars = {}

    def _try_enter(self, slice: Slice):
        if self.exit_block_date == self.Time.date():
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Invested:
                return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        min_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= min_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        expiry = expiries[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * current_price
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted call entry: " + str(selected.Symbol))

    def _evaluate_open_position(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        option_quote = slice.QuoteBars.get(self.held_symbol)
        if option_quote is not None:
            bid = option_quote.Bid.Close
            ask = option_quote.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        expiration = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiration)

        if (self.Time.date() == prior_trading_day and
                self.Time.time() >= time(15, 45)):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed:
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug("Submitted option exit: " + reason)

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed:
            self.entry_ticket.Cancel("Exit submitted.")

    def _handle_expiration_processing(self, today):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if today >= expiry:
            self.exit_block_date = today
            if self.Portfolio[self.held_symbol].Invested:
                self._submit_exit("expiration processing")

    def _handle_equity_created_by_exercise(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self.Liquidate(self.spy)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Call entry filled at " +
                        str(self.entry_price)
                    )
                elif order_event.Status == OrderStatus.Canceled:
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Call exit filled at " +
                               str(order_event.FillPrice))
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None

        if order_event.Symbol == self.spy and order_event.FillQuantity != 0:
            self.Debug("Unexpected SPY exercise or assignment order event.")
            self.Liquidate(self.spy)

    def _previous_trading_day(self, target_date):
        candidate = target_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)
        return candidate
