from AlgorithmImports import *
from datetime import timedelta
from QuantConnect.Data.Market import TradeBar


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.entry_order = None
        self.exit_order = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_today = False
        self.last_expiration_check_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        # TradeBarConsolidator emits bars only when actual input data arrives.
        # Minute SPY data is regular-session data and uses New York time.
        if bar.Symbol != self.spy:
            return

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossover_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= crossover_time <= time(14, 30)

        self.pending_crossover = (
            eligible_time
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_expiration_check_date != current_date:
            self.last_expiration_check_date = current_date
            self.no_entry_today = False

        self.HandleExpirationAndTimeStop(slice)

        if self.no_entry_today:
            self.pending_crossover = False
            return

        if self.IsOptionHolding():
            self.EvaluateProfitTarget(slice)
            self.pending_crossover = False
            return

        if self.entry_order is not None and self.IsOrderOpen(self.entry_order):
            self.pending_crossover = False
            return

        if getattr(self, "pending_crossover", False):
            self.pending_crossover = False
            self.TryEnter(slice)

        # Assignment or exercise can create SPY shares unexpectedly.
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; liquidating."
            )
            self.MarketOrder(self.spy, -spy_holding.Quantity)
            self.no_entry_today = True

    def TryEnter(self, slice: Slice):
        if self.IsOptionHolding():
            return

        if self.entry_order is not None and self.IsOrderOpen(self.entry_order):
            return

        if self.spy not in slice.Bars:
            self.Debug(f"{self.Time}: Entry skipped; no current SPY bar.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped; invalid SPY price.")
            return

        chains = slice.OptionChains
        if chains is None or len(chains) == 0:
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        for chain in chains.Values:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying expiration or call."
            )
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in contracts
        )

        strike_floor = spy_price * 1.01
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not eligible:
            self.Debug(
                f"{self.Time}: Entry skipped; no call strike >= 101% of SPY."
            )
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_order = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for {selected.Symbol}; "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike:.2f}."
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_order is not None and self.IsOrderOpen(self.exit_order):
            return

        if self.held_option not in slice.OptionChains:
            # The contract may still have quote data even when its chain is absent.
            quote = slice.QuoteBars.get(self.held_option)
        else:
            quote = slice.QuoteBars.get(self.held_option)

        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.CancelOpenExitOrder()
                self.exit_order = self.MarketOrder(
                    self.held_option, -quantity
                )
                self.Debug(
                    f"{self.Time}: Profit target reached; "
                    f"midpoint={midpoint:.2f}, entry={self.entry_price:.2f}."
                )

    def HandleExpirationAndTimeStop(self, slice: Slice):
        if self.held_option is None or not self.IsOptionHolding():
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.no_entry_today = True
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.CancelOpenExitOrder()
                if self.exit_order is None or not self.IsOrderOpen(self.exit_order):
                    self.exit_order = self.MarketOrder(
                        self.held_option, -quantity
                    )
                    self.Debug(
                        f"{self.Time}: Expiration processing; "
                        f"liquidating {self.held_option}."
                    )
            return

        if today == expiry - timedelta(days=1):
            if self.Time.time() >= time(15, 45):
                self.no_entry_today = True
                quantity = self.Portfolio[self.held_option].Quantity
                if quantity != 0:
                    self.CancelOpenExitOrder()
                    if self.exit_order is None or not self.IsOrderOpen(self.exit_order):
                        self.exit_order = self.MarketOrder(
                            self.held_option, -quantity
                        )
                        self.Debug(
                            f"{self.Time}: Time stop; liquidating "
                            f"{self.held_option} before expiration."
                        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order is not None
            and order_event.OrderId == self.entry_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_option} "
                    f"at {self.entry_price:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.Debug(
                    f"{self.Time}: Entry order did not fill: "
                    f"{order_event.Status}."
                )
                self.entry_order = None

        if (
            self.exit_order is not None
            and order_event.OrderId == self.exit_order.OrderId
            and order_event.Status == OrderStatus.Filled
